/*---------------------------------------------------------------------------------------------
 *  Copyright (c) Frappe Studio contributors. All rights reserved.
 *  Licensed under the MIT License. See License.txt in the project root for license information.
 *--------------------------------------------------------------------------------------------*/

import { Event } from '../../../../base/common/event.js';
import { Disposable, MutableDisposable, toDisposable } from '../../../../base/common/lifecycle.js';
import { generateUuid } from '../../../../base/common/uuid.js';
import { Codicon } from '../../../../base/common/codicons.js';
import { ACTIVE_GROUP, IEditorService } from '../../../services/editor/common/editorService.js';
import { IWebviewWorkbenchService, IWebViewShowOptions } from '../../webviewPanel/browser/webviewWorkbenchService.js';
import { WebviewInitInfo } from '../../webview/browser/webview.js';
import { WebviewInput } from '../../webviewPanel/browser/webviewEditorInput.js';

/**
 * Base class for Frappe Studio webview-based editors.
 *
 * Webviews are untrusted by design in the workbench; Frappe Studio therefore:
 * - serves every editor with a strict content security policy (no remote resources, no eval),
 * - keeps API capabilities and session state strictly on the host side,
 * - exchanges state exclusively through typed `postMessage` contracts.
 */
export abstract class FrappeWebviewController<Incoming extends { type: string }, Outgoing extends { type: string }> extends Disposable {

	/** The unique per-application view type used by the workbench webview service. */
	abstract readonly viewType: string;
	/** Icon shown on the editor tab. */
	abstract readonly icon: typeof Codicon.bug;

	/** Current open input; updated by subclasses via `openEditor`. */
	protected input: WebviewInput | undefined;

	private readonly _onDidReceiveMessage: Event<Incoming> = this._messageEmitter.event;
	private readonly _messageEmitter = new MutableDisposable();
	/** Outgoing message queue used while a webview is loading. */
	constructor(
		descendants = undefined,
		@IWebviewWorkbenchService protected readonly webviewWorkbenchService: IWebviewWorkbenchService,
		@IEditorService private readonly editorService: IEditorService
	) {
		super();
	}

	/**
	 * Opens (or reveals) a webview editor for this controller, wiring the message channel.
	 * Returns the html container for subclasses to set initial content on.
	 */
	protected async openEditor(title: string, onMessage: (message: Incoming) => void): Promise<void> {
		if (this.input) {
			this.webviewWorkbenchService.revealWebview(this.input, ACTIVE_GROUP, false);
			return;
		}
		const initInfo: WebviewInitInfo = {
			title,
			providedViewType: this.viewType,
			options: { enableFindWidget: true },
			contentOptions: { localResourceRoots: [], allowScripts: true },
			extension: undefined
		};
		const showOptions: IWebViewShowOptions = { group: ACTIVE_GROUP, preserveFocus: false };
		const input = this.webviewWorkbenchService.openWebview(initInfo, this.viewType, title, undefined, showOptions);
		this.input = input;
		const disposables = this._register(new MutableDisposable());
		disposables.value = toDisposable(() => undefined);
		input.onWillDispose(() => { this.input = undefined; });
		input.webview.onConnectionStateChanged(undefined, undefined, toDisposable(() => undefined));
		// attach a message listener wired through the subclass hook
		input.webview.onMessage(e => {
			const message = e.message as Incoming | undefined;
			if (message && typeof message === 'object' && typeof message.type === 'string') {
				onMessage(message);
			}
		});
		this._messageEmitter.value = toDisposable(() => undefined);
		this.onDidReceiveMessage(() => undefined);
		this.currentBuffering = input;
		this.editorService.openEditor(input, { preserveFocus: false });
	}

	private currentBuffering: WebviewInput | undefined;

	/** Replaces the webview HTML. Subclasses pass complete, CSP-secured documents. */
	protected setHtml(html: string): void {
		this.input?.webview.setHtml(html);
	}

	/** Posts a typed message into the webview. Failures land softly; the webview is untrusted. */
	protected post(message: Outgoing): void {
		void this.input?.webview.postMessage(message);
	}
}

/*---------------------------------------------------------------------------------------------
