function extractList<T>(payload: unknown): T[] {
	if (Array.isArray(payload)) {
		return payload as T[];
	}
	if (payload && typeof payload === 'object' && Array.isArray((payload as { data?: unknown }).data)) {
		return (payload as { data: T[] }).data;
	}
	return [];
}

