}

// ---- Host -> Webview messages -------------------------------------------------------------
export interface InitDoctypeMessage { readonly type: 'init'; readonly rawJson: JsonRecord; readonly doctypeName: string | undefined; readonly site: string; readonly readOnly: boolean; readonly frappeMajor: number | undefined }
export interface SaveResultMessage { readonly type: 'saveResult'; readonly ok: boolean; readonly message: string | undefined; readonly refreshedRawJson: JsonRecord | undefined }
export interface SaveBlockedMessage { readonly type: 'saveBlocked'; readonly message: string }
export interface HostNoticeMessage { readonly type: 'notice'; readonly level: 'info' | 'warn' | 'error'; readonly message: string }

export type DoctypeEditorOutgoing = InitDoctypeMessage | SaveResultMessage | SaveBlockedMessage | HostNoticeMessage;

// ---- Webview -> Host messages -------------------------------------------------------------
export interface ReadyMessage { readonly type: 'ready' }
export interface SaveRequestedMessage { readonly type: 'save'; readonly rawJson: JsonRecord }
export interface ReloadRequestedMessage { readonly type: 'reload' }
export interface DeleteRequestedMessage { readonly type: 'delete' }

export type DoctypeEditorIncoming = ReadyMessage | SaveRequestedMessage | ReloadRequestedMessage | DeleteRequestedMessage;

export class DoctypeEditorController extends FrappeWebviewController<DoctypeEditorIncoming, DoctypeEditorOutgoing> {

	protected readonly editorViewType = 'frappeStudio.doctypeEditor';

	private openInfo: DoctypeEditorOpenInfo | undefined;
	private baselineJson: JsonRecord | undefined;
	private baselineModified: string | undefined;
	private siteClient: IFrappeClient | undefined;
	private readonly tokenSource = new CancellationTokenSource();

	static create(instantiationService: IInstantiationService): DoctypeEditorController {
		return instantiationService.createInstance(DoctypeEditorController);
	}

	constructor(
		@ISiteConnectionService private readonly connectionService: ISiteConnectionService,
		@ILogService private readonly logService: ILogService
	) {
		super(connectionService, (connectionId) => this.lookupClient(connectionId), new EmptyFocusHandler());
	}

	private lookupClient(connectionId: string): IFrappeClient {
		const session = this.connectionService.getSession(connectionId) ?? this.connectionService.getSessions().find(s => s.connection.id === connectionId);
		if (!session) {
			throw new Error(localize('frappeStudio.noSession', 'No connected session for this site.'));
		}
		return session.client;
	}

	/** Opens (or focuses) the visual DocType Studio for a site. */
	async show(openInfo: DoctypeEditorOpenInfo): Promise<void> {
		this.openInfo = openInfo;
		this.siteClient = this.lookupClient(openInfo.connectionId);
		const title = openInfo.doctypeName
			? localize({ key: 'frappeStudio.doctypeEditorTitle', comment: ['{0} is the DocType name'] }, 'DocType Studio: {0}', openInfo.doctypeName)
			: localize('frappeStudio.newDoctypeEditorTitle', 'DocType Studio: New DocType');
		this.openEditor(title, () => buildDoctypeEditorDocument(newFrappeNonceForEditor()));
	}

	protected handleMessage(message: DoctypeEditorIncoming): void {
		this.dispatchInternal(message);
	}

	private dispatchInternal(message: DoctypeEditorIncoming): void {
		switch (message.type) {
			case 'ready':
				void this.pushInit();
				return;
			case 'reload':
				void this.pushInit();
				return;
			case 'save':
				void this.save(message.rawJson);
				return;
			case 'delete':
				void this.deleteCurrent();
				return;
		}
	}

	private async pushInit(): Promise<void> {
		const info = this.openInfo;
		const client = this.siteClient;
		if (!info || !client) {
			return;
		}
		try {
			let rawJson: JsonRecord;
			let baselineModified: string | undefined;
			if (info.doctypeName) {
				const doc = await getDoctypeDocument(client, info.doctypeName, this.tokenSource.token);
				rawJson = doc;
				baselineModified = typeof doc['modified'] === 'string' ? doc['modified'] : undefined;
			} else {
				rawJson = newDoctypeSkeleton();
			}
			this.baselineJson = rawJson;
			this.baselineModified = baselineModified;
			const versions = (await this.connectionService.getSession(info.connectionId))?.versions;
			const readOnly = !this.connectionService.getSessions().some(s => s.connection.id === info.connectionId);
			this.post({
				type: 'init',
				rawJson,
				doctypeName: info.doctypeName,
				site: info.siteOrigin,
				readOnly,
				frappeMajor: parseMajorVersion(versions?.frappe)
			});
		} catch (error) {
			this.logService.warn('[Frappe Studio] DocType init failed', error instanceof Error ? error.name : String(error));
			this.post({ type: 'notice', level: 'error', message: describeError(error) });
		}
	}

	private async save(candidate: JsonRecord): Promise<void> {
		const info = this.openInfo;
		const client = this.siteClient;
		if (!info || !client) {
			return;
		}
		try {
			validateDocType(candidate);
			if (this.baselineJson) {
				// keep unrelated top-level keys exactly as the server sent them
				const diff = diffMetadata(this.baselineJson, candidate).length;
				if (diff === 0 && info.doctypeName) {
					this.post({ type: 'notice', level: 'info', message: localize('frappeStudio.noChanges', 'There were no changes to save.') });
					return;
				}
			}
			if (info.doctypeName) {
				await updateDoctype(client, candidate, this.tokenSource.token);
			} else {
				const created = await createDocType(client, { ...candidate, new: 1 }, this.tokenSource.token);
				const newRecord = created.message?.['name'];
				if (typeof newRecord === 'string') {
					this.openInfo = { ...info, doctypeName: newRecord };
				}
			}
			// Reload and verify so the editor state is the truth the server accepted,
			// and external modifications since open become visible immediately.
			await this.pushInit();
			this.post({ type: 'saveResult', ok: true, message: localize('frappeStudio.saved', 'Saved.') , refreshedRawJson: undefined });
		} catch (error) {
			const message = error instanceof MetadataValidationError || error instanceof Error ? error.message : String(error);
			this.logService.debug('[Frappe Studio] doc save failed', error instanceof Error ? error.name : String(error));
			this.post({ type: 'saveResult', ok: false, message, refreshedRawJson: undefined });
		}
	}

	private async deleteCurrent(): Promise<void> {
		const info = this.openInfo;
		const client = this.siteClient;
		if (!info?.doctypeName || !client) {
			return;
		}
		try {
			await deleteDocType(client, info.doctypeName, this.tokenSource.token);
			this.post({ type: 'saveResult', ok: true, message: localize('frappeStudio.deleted', 'Deleted.'), refreshedRawJson: undefined });
			this.input?.dispose();
		} catch (error) {
			this.post({ type: 'saveResult', ok: false, message: describeError(error), refreshedRawJson: undefined });
		}
	}
}

