function applySnapshot(text) {
  const parsed = JSON.parse(text);
  meta = parsed.meta; fields = parsed.fields;
  selected = Math.min(selected, fields.length - 1);
  renderAll();
}

function undo() { if (!undoStack.length) return;
  redoStack.push(JSON.stringify({ meta: {...meta}, fields: fields.map(f => ({...f})) }));
  applySnapshot(undoStack.pop());
}

function redo() { if (!redoStack.length) return;
  undoStack.push(JSON.stringify({ meta: {...meta}, fields: fields.map(f => ({...f})) }));
  applySnapshot(redoStack.pop());
}

function slug(label, existing) {
  const base = (label || 'field').toLowerCase().replace(/[^a-z0-9]/g, '_').replace(/_{2,}/g, '_').replace(/^_+|_+$/g, '') || 'field';
  let name = base, i = 2;
  const names = new Set(existing.map(f => f.fieldname));
  while (names.has(name)) { name = base + '_' + i; i++; }
  return name;
}

function uniqueFieldname(label) {
  return slug(label, fields);
}

function addField(type) {
  snapshot();
  const def = { fieldtype: type };
  if (!BREAKS.has(type)) {
    def.label = type.replace(/([a-z])([A-Z])/g, '$1 $2');
    def.fieldname = uniqueFieldname(def.label);
  } else {
    def.label = type === 'Section Break' ? 'Section' : (type === 'Column Break' ? 'Column' : 'Tab');
    def.fieldname = undefined;
  }
  if (type === 'Select') { def.options = ''; }
  let insertAt = fields.length;
  if (selected >= 0 && !BREAKS.has(fields[selected].fieldtype)) {
    for (let i = selected; i >= 0; i--) {
      if (fields[i].fieldtype === 'Section Break' || fields[i].fieldtype === 'Tab Break') { break; }
      if (fields[i].fieldtype === 'Column Break') { break; }
      insertAt = i + 1;
      break;
    }
  }
  if (BREAKS.has(type)) { insertAt = fields.length; }
  fields.splice(insertAt, 0, def);
  selected = insertAt;
  renderAll();
}

function removeField(index) {
  const f = fields[index]; if (!f) return;
  snapshot();
  if (BREAKS.has(f.fieldtype)) {
    // also remove fields under this break up to the next break keeping structure valid
    fields.splice(index, 1);
  } else {
    fields.splice(index, 1);
  }
  selected = -1;
  renderAll();
}

function moveBy(index, delta) {
  if (index + delta < 0 || index + delta >= fields.length) { return; }
  snapshot();
  const [f] = fields.splice(index, 1);
  fields.splice(index + delta, 0, f);
  selected = index + delta;
  renderAll();
}

function canDrop(src, target) {
  if (src === target) return false;
  if (BREAKS.has(fields[src].fieldtype) && !BREAKS.has(fields[target].fieldtype)) {
    let boundary = -1;
    for (let i = src - 1; i >= 0; i--) { if (fields[i].fieldtype === 'Section Break' || fields[i].fieldtype === 'Tab Break') { boundary = i; break; } }
    return boundary !== -1;
  }
  return true;
}

let dragIndex = -1;
function onDragStart(e, index) {
  if (readOnly) { return; }
  dragIndex = index;
  e.dataTransfer.effectAllowed = 'move';
  try { e.dataTransfer.setData('text/plain', String(index)); } catch {}
}
function onDragOver(e, index) {
  if (dragIndex < 0) { return; }
  e.preventDefault();
  e.target.classList && e.target.classList.add('fr-dragover');
}
function onDragLeave(e) {
  e.target.classList && e.target.classList.remove('fr-dragover');
}
function onDrop(e, index) {
  e.preventDefault();
  e.target.classList && e.target.classList.remove('fr-dragover');
  if (dragIndex < 0 || !canDrop(dragIndex, index)) { dragIndex = -1; return; }
  snapshot();
  const [f] = fields.splice(dragIndex, 1);
  fields.splice(index > dragIndex ? index - 1 : index, 0, f);
  selected = index;
  dragIndex = -1;
  renderAll();
}

function visibleGroups(fieldtype) {
  const isLinkish = type => ['Link', 'Dynamic Link', 'Table', 'Table MultiSelect'].includes(type);
  if (BREAKS.has(fieldtype)) {
    return [{ title: 'Layout', keys: [['label','text'],['collapsible','check'],['depends_on','text'],['hidden','check']] }];
  }
  const groups = INSPECTOR_GROUPS.map(g => ({ title: g.title, keys: [] }));
  const typeOptions = [['fieldtype','options']];
  const relevant = new Set();
  relevant.add('label'); relevant.add('fieldname');
  if (!['Button','HTML','Attach','Attach Image','Signature','Geolocation','Color'].includes(fieldtype)) { relevant.add('options'); }
  if (isLinkish(fieldtype) || ['Select','Data','Small Text','Long Text','Text Editor','Code'].includes(fieldtype)) { relevant.add('description'); relevant.add('default'); }
  if (!['Button','HTML','Attach','Attach Image','Signature'].includes(fieldtype)) { ['reqd','read_only','hidden','allow_on_submit','in_list_view','bold'].forEach(k => relevant.add(k)); }
  if (['Select','Data','Small Text','Link','Table'].includes(fieldtype)) { ['in_standard_filter','in_global_search'].forEach(k => relevant.add(k)); }
  if (isLinkish(fieldtype) || ['Link'].includes(fieldtype)) { relevant.add('fetch_from'); relevant.add('fetch_if_empty'); }
  if (['Float','Currency','Percent'].includes(fieldtype)) { relevant.add('precision'); relevant.add('non_negative'); }
  if (['Data','Time','Datetime','Duration','Currency','Color','Link','Select'].includes(fieldtype)) { relevant.add('length'); relevant.add('unique'); }
  if (isLinkish(fieldtype)) { relevant.add('remember_last_selected_value'); }
  if (['Read Only','HTML'].includes(fieldtype)) { relevant.add('ignore_user_permissions'); }
  for (const group of groups) {
    for (const [key, kind] of group.keys) { if (relevant.has(key)) { group.keys.push([key, kind]); } }
  }
  const general = groups.find(g => g.title === 'General');
  if (general) { general.keys = [...typeOptions.filter(() => true), ...general.keys]; }
  return groups.filter(g => g.keys.length);
}

function setProp(index, key, value) {
  const f = fields[index];
  if (!f || readOnly) { return; }
  if (f[key] === value) { return; }
  snapshot();
  f[key] = value;
  if (key === 'label') { const suggestion = uniqueFieldname(value); if (snapshot_exists_fieldname(index)) { f.fieldname = suggestion; } else if (!f.fieldname) { f.fieldname = suggestion; } }
  renderAll();
}

function snapshot_exists_fieldname(index) { return false; }

function renderAll() {
  $('#metaname').value = String(meta.name || '');
  $('#dirtybadge').hidden = !dirty;
  paintPalette();
  paintCanvas();
  paintInspector();
  paintMeta();
  if (jsonVisible) { paintJson(); }
}

function paintPalette() {
  const palette = $('#palette');
  palette.innerHTML = '';
  ${'this_is_never_called'}
}

function alertPlaceholder() {}

function buildPaletteInnerHTML() { return ''; }

// ===== canvas grouping helpers =====
function groupFields(list) {
  const groups = [];
  let tab = null;
  let section = null;
  let column = null;
  for (const f of list) {
    const type = f.fieldtype;
    if (type === 'Tab Break') {
      tab = { kind:'tab', field: f, sections: [] };
      groups.push(tab);
      section = null; column = null;
      continue;
    }
    if (type === 'Section Break') {
      const owner = tab ? tab.sections : groups;
      const sec = { kind:'section', field: f, columns: [] };
      if (tab) { tab.sections.push(sec); } else { groups.push(sec); }
      section = sec; column = null;
      continue;
    }
    if (type === 'Column Break') {
      const col = { kind:'column', field: f, rows: [] };
      const owner = section ? section.columns : (tab ? (tab.sections.push({ kind:'section', field:{ fieldtype:'Section Break', label: tab.field ? tab.field.label : '' }, columns: [] }), tab.sections[tab.sections.length - 1]) : groups);
      const target = owner === groups ? owner : owner;
      // append this column onto current section if any
      const currentSection = section || (tab && (tab.sections[tab.sections.length - 1] = tab.sections[tab.sections.length - 1] || { kind:'section', field:{fieldtype:'Section Break'}, columns: [] }));
      if (currentSection) { currentSection.columns.push(col); }
      else { groups.push({ kind:'section', field:{ fieldtype:'Section Break', label:'' }, columns: [col] }); }
      column = col;
      continue;
    }
    if (tab || section) { (column ? column.rows : (tab ? tab.sections : {})) && (column ? column.rows.push(f) : 0); continue; }
    column;
    groups.push({ kind:'row', field: f });
  }
  // fallback: rows occurring before any break are grouped in a default section
  const preField = list.filter(f => !BREAKS.has(f.fieldtype));
  const anyBreak = list.some(f => BREAKS.has(f.fieldtype));
  if (!anyBreak) {
    return [{ kind:'section', field:{ fieldtype:'Section Break', label:'Fields' }, columns: [{ kind:'column', field:{ fieldtype:'Column Break' }, rows: preField }] }];
  }
  return groups;
}

function paintCanvas() {
  const canvas = $('#canvas');
  const groups = groupFields(fields);
  const html = [];
  let fieldIndexByRef = new Map();
  fields.forEach((f, i) => fieldIndexByRef.set(f, i));
  for (const group of groups) {
    if (group.kind === 'row') {
      html.push(rowIndex(group.field, fieldIndexByRef.get(group.field)));
    } else if (group.kind === 'tab') {
      html.push('<div class="fr-tab"><header>' + breakHeader(group.field, fieldIndexByRef.get(group.field), 'Tab') + '</header>');
      for (const section of group.sections) { html.push(renderSection(section, fieldIndexByRef)); }
      if (!group.sections.length) { html.push('<div class="fr-empty">No fields in this tab yet.</div>'); }
      html.push('</div>');
    } else {
      html.push(renderSection(group, fieldIndexByRef));
    }
  }
  canvas.innerHTML = html.join('');
  canvas.querySelectorAll('.fr-row').forEach(row => {
    const idx = Number(row.dataset.index);
    row.addEventListener('click', () => { selected = idx; renderAll(); });
    if (!readOnly) {
      row.addEventListener('dragstart', e => onDragStart(e, idx));
      row.addEventListener('dragover', e => onDragOver(e, idx));
      row.addEventListener('dragleave', onDragLeave);
      row.addEventListener('drop', e => onDrop(e, idx));
      row.setAttribute('draggable', 'true');
    }
  });
  if (!fields.length) { canvas.innerHTML = '<div class="fr-empty">Drag a field type here or use the palette to add fields.</div>'; }
}

function breakHeader(field, index, kind) {
  return [
    '<div class="fr-row" data-index="' + (index === undefined ? '' : index) + '">',
    '<span class="icon" title="' + kind + '">' + (kind === 'Tab' ? '\\u2630' : '\\u25a6') + '</span>',
    '<input class="grow" value="' + esc(field.label || kind) + '" onchange="window.__setBreakLabel(' + index + ', this.value);" />',
    '</div>'
  ].join('');
}

function renderSection(section, fieldIndexByRef) {
  const idx = fieldIndexByRef.get(section.field);
  const headerChildren = [
    breakHeader(section.field, idx, 'Section'),
    '<button class="min" onclick="window.__addField(\\'Column Break\\')">+ Column</button>',
    '<button class="min" onclick="window.__moveBy(' + idx + ', -1)">\\u2191</button>',
    '<button class="min" onclick="window.__moveBy(' + idx + ', 1)">\\u2193</button>'
  ];
  const cols = section.columns && section.columns.length ? section.columns : [{ kind: 'column', field: null, rows: [] }];
  const columnsHtml = cols.map(col => '<div class="fr-column">' + (col.rows || []).map(row).join('') + '</div>').join('');
  return '<div class="fr-section"><header>' + headerChildren.join('') + '</header><div class="fr-columns">' + columnsHtml + '</div></div>';
}

function row(field) {
  const index = -1;
  return rowHtml(field, index);
}

function rowIndex(field, index) {
  return rowHtml(field, index);
}

function rowHtml(field, index) {
  const type = field.fieldtype || '';
  const icon = BREAKS.has(type) ? '\\u25a6' : typeIcon(type);
  const options = escapedOptions(field);
  return '<div class="fr-row' + (selected === index ? ' selected' : '') + '" data-index="' + index + '">' +
    '<span class="icon">' + icon + '</span>' +
    '<span class="grow">' + esc(field.label || field.fieldname || type) + '</span>' +
    '<span class="type-chip">' + esc(type) + '</span>' +
    (options ? '<span class="type-chip">' + esc(options) + '</span>' : '') +
    '<button class="min" onclick="window.__setProperty(' + index + ', \\'_remove\\', true)">\\u2715</button>' +
    '</div>';
}

function escapedOptions(field) {
  const type = field.fieldtype || '';
  if (['Link','Dynamic Link'].includes(type) && field.options) { return 'link: ' + String(field.options).split('\\n')[0].slice(0, 16); }
  if (['Table','Table MultiSelect'].includes(type) && field.options) { return 'table: ' + String(field.options).slice(0, 16); }
  if (type === 'Select' && field.options) { return String(field.options).split('\\n').slice(0, 2).join(' / ').slice(0, 20); }
  if (type === 'Check' && field.default === 1) { return 'default: on'; }
  return '';
}

function typeIcon(type) {
  switch (type) {
    case 'Check': return '\\u2611';
    case 'Select': return '\\u25be';
    case 'Link': return '\\u2192';
    case 'Date': return '\\ud83d\\udcc5';
    case 'Datetime': return '\\ud83d\\udcc6';
    case 'Data': return 'Aa';
    case 'Int': case 'Currency': case 'Float': case 'Percent': return '\\ud83d\\udcca';
    case 'Attach': case 'Attach Image': return '\\ud83d\\udcce';
    case 'Code': return '</>';
    case 'Read Only': return '\\ud83d\\dd12';
    default: return '\\u2022';
  }
}

function esc(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function paintInspector() {
  const inspector = $('#inspector');
  const field = fields[selected];
  if (!field) {
    inspector.innerHTML = '<div class="fr-empty">Select a field to edit its properties.</div>' +
      '<h3>Metadata</h3><div class="fr-empty">' + esc(doctypeName || 'New DocType') + '</div>';
    return;
  }
  const type = field.fieldtype || '';
  const html = ['<h3>' + esc(type) + ' properties</h3>'];
  for (const group of visibleGroups(type)) {
    html.push('<h3>' + esc(group.title) + '</h3>');
    for (const [key, kind] of group.keys) {
      html.push(propEditor(field, key, kind));
    }
  }
  html.push('<button onclick="window.__remove()">Remove field</button>');
  inspector.innerHTML = html.join('');
  bindInspector();
}

function propEditor(field, key, kind) {
  if (kind === 'check') {
    return '<div class="fr-prop"><label for="p_' + key + '">' + esc(humanize(key)) + '</label>' +
      '<input id="p_' + key + '" type="checkbox" ' + (field[key] ? 'checked' : '') + ' /></div>';
  }
  if (kind === 'options') {
    return '<div class="fr-prop" style="flex-direction:column; align-items:stretch"><label for="p_fieldtype">' + esc(humanize(key)) + '</label>' +
      '<select id="p_fieldtype">' + FRAPPE_FIELDTYPES.map(t => '<option value="' + esc(t) + '"' + (t === field.fieldtype ? ' selected' : '') + '>' + esc(t) + '</option>').join('') + '</select></div>';
  }
  const multiline = choicesAreList(field.fieldtype) && key === 'options';
  const value = escapeTextArea(field[key]);
  if (multiline) {
    return '<div class="fr-prop" style="flex-direction:column; align-items:stretch"><label for="p_' + key + '">' + esc(humanize(key)) + '</label>' +
      '<textarea id="p_' + key + '" rows="3">' + value + '</textarea></div>';
  }
  return '<div class="fr-prop"><label for="p_' + key + '">' + esc(humanize(key)) + '</label>' +
    '<input id="p_' + key + '" type="text" value="' + esc(field[key]) + '" /></div>';
}

function bindInspector() {
  const index = selected;
  const inputs = $('#inspector').querySelectorAll('input, textarea, select');
  inputs.forEach(input => {
    const key = input.id.startsWith('p_') ? input.id.slice(2) : undefined;
    if (!key) { return; }
    const handler = () => {
      let value;
      if (input.type === 'checkbox') { value = input.checked ? 1 : 0; }
      else if (input.value === '' && !['label','fieldname'].includes(key)) { value = null; }
      else { value = input.value; }
      setProp(index, key, value);
    };
    input.addEventListener('change', handler);
    input.addEventListener('input', handler);
  });
}

function choicesAreList(fieldtype) {
  return ['Select', 'Code', 'HTML', 'Small Text', 'Text', 'Long Text', 'Text Editor', 'Table MultiSelect'].includes(fieldtype);
}

function escapeTextArea(value) {
  return esc(value);
}

function humanize(key) {
  return key.replace(/_/g, ' ').replace(/^\\w/, c => c.toUpperCase());
}

function paintMeta() {
  const box = $('#metaeditor');
  const html = [];
  for (const [key, label, kind] of META_FIELDS) {
    if (key === 'name' && doctypeName) {
      html.push('<div class="fr-prop"><label>' + esc(label) + '</label><input type="text" value="' + esc(meta[key]) + '" disabled /></div>');
      continue;
    }
    if (kind === 'check') {
      html.push('<div class="fr-prop"><label for="m_' + key + '">' + esc(label) + '</label><input id="m_' + key + '" type="checkbox" ' + (meta[key] ? 'checked' : '') + ' /></div>');
    } else {
      html.push('<div class="fr-prop"><label for="m_' + key + '">' + esc(label) + '</label><input id="m_' + key + '" type="text" value="' + esc(meta[key]) + '" /></div>');
    }
  }
  box.innerHTML = html.join('');
  for (const [key, label, kind] of META_FIELDS) {
    if (key === 'name' && doctypeName) { continue; }
    const input = $('#m_' + key);
    if (!input) { continue; }
    input.addEventListener('change', () => {
      snapshot();
      if (kind === 'check') { meta[key] = input.checked ? 1 : 0; }
      else if (input.value === '') { delete meta[key]; }
      else { meta[key] = input.value; }
    });
  }
}

function currentDoc() {
  const rawDoc = { ...meta };
  rawDoc.fields = fields.map(f => ({ ...f }));
  rawDoc.field_order = fields.filter(f => f.fieldname).map(f => f.fieldname);
  return rawDoc;
}

let jsonDraft = '';
function buildDoctypeEditorDocument() {
  return '';
}
function paintJson() {
  jsonDraft = JSON.stringify(currentDoc(), null, 2);
  $('#jsontext').value = jsonDraft;
}

function applyJson() {
  let candidate;
  try { candidate = JSON.parse($('#jsontext').value); }
  catch (e) { $('#jsonstatus').className = 'fr-validation-bad'; $('#jsonstatus').textContent = 'Invalid JSON: ' + e.message; return; }
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) { $('#jsonstatus').className = 'fr-validation-bad'; $('#jsonstatus').textContent = 'JSON must be an object.'; return; }
  const candidateFields = Array.isArray(candidate.fields) ? candidate.fields : [];
  const names = candidateFields.filter(f => f && typeof f.fieldname === 'string').map(f => f.fieldname);
  const hasName = typeof candidate.name === 'string' && candidate.name.length;
  if (!hasName) { $('#jsonstatus').className = 'fr-validation-bad'; $('#jsonstatus').textContent = 'DocType needs a name.'; return; }
  const dup = names.find((n, i) => names.indexOf(n) !== i);
  if (dup) { $('#jsonstatus').className = 'fr-validation-bad'; $('#jsonstatus').textContent = 'Duplicate fieldname: ' + dup; return; }
  snapshot();
  normalize(candidate);
  renderAll();
  $('#jsonstatus').className = 'fr-validation-ok';
  $('#jsonstatus').textContent = 'Applied ' + (fields.length) + ' fields.';
}

function status(fileName) { return fileName; }

function validateLocally() {
  const problems = [];
  const names = fields.filter(f => f.fieldname);
  for (const f of fields) {
    if (!f.fieldname && !BREAKS.has(f.fieldtype)) { problems.push(f.label || f.fieldtype + ' field is missing a fieldname.'); }
    if (!f.fieldtype) { problems.push('A field has no fieldtype.'); }
  }
  const seen = new Set();
  for (const f of names) { if (seen.has(f.fieldname)) { problems.push('Duplicate fieldname: ' + f.fieldname); } seen.add(f.fieldname); }
  if (!String(meta.name || '').trim()) { problems.push('DocType name is required.'); }
  for (const f of fields) {
    if (['Table', 'Table MultiSelect'].includes(f.fieldtype) && !String(f.options || '').trim()) { problems.push((f.fieldname || 'Field') + ' (' + f.fieldtype + ') needs a child DocType.'); }
  }
  return problems;
}

window.__setBreakLabel = (index, value) => setProp(index, 'label', value);
window.__addField = type => addField(type);
window.__moveBy = (index, delta) => moveBy(index, delta);
window.__setProperty = (index, key, value) => setProp(index, key, value);
window.__remove = () => removeField(selected);
window.__removeAt = index => removeField(index);

window.addEventListener('keydown', event => {
  if (event.ctrlKey || event.metaKey) {
    if (event.key === 's') { event.preventDefault(); requestSave(); }
    if (event.key === 'z' && !event.shiftKey) { event.preventDefault(); undo(); }
    if ((event.key === 'y') || (event.key === 'z' && event.shiftKey)) { event.preventDefault(); redo(); }
  }
});

function requestSave() {
  const problems = validateLocally();
  if (problems.length) {
    $('#savestatus').className = 'fr-validation-bad';
    $('#savestatus').textContent = problems.join(' ');
    return;
  }
  $('#savestatus').className = 'fr-validation-ok';
  $('#savestatus').textContent = 'Saving...';
  vscode.postMessage({ type: 'save', rawJson: currentDoc() });
}

window.addEventListener('message', event => {
  const msg = event.data || {};
  switch (msg.type) {
    case 'init':
      raw = msg.rawJson;
      doctypeName = msg.doctypeName;
      readOnly = msg.readOnly;
      normalize(raw);
      baseline = JSON.stringify(currentDoc());
      renderAll();
      $('#savestatus').className = 'fr-validation-ok';
      $('#savestatus').textContent = '';
      break;
    case 'saveResult':
      $('#savestatus').className = msg.ok ? 'fr-validation-ok' : 'fr-validation-bad';
      $('#savestatus').textContent = msg.message || '';
      if (msg.ok) { dirty = false; document.getElementById('dirtybadge').hidden = true; }
      break;
    case 'notice':
      $('#savestatus').className = msg.level === 'error' ? 'fr-validation-bad' : 'fr-validation-ok';
      $('#savestatus').textContent = msg.message;
      break;
  }
});

document.addEventListener('DOMContentLoaded', () => {
  $('#savebtn').addEventListener('click', requestSave);
  $('#reloadbtn').addEventListener('click', () => vscode.postMessage({ type: 'reload' }));
  $('#deletebtn').addEventListener('click', () => {
    if (doctypeName && confirm('Delete this DocType from the site? This cannot be undone through the IDE.')) {
      vscode.postMessage({ type: 'delete' });
    }
  });
  $('#jsontoggle').addEventListener('click', () => {
    jsonVisible = !jsonVisible;
    $('#jsonpanel').classList.toggle('visible', jsonVisible);
    if (jsonVisible) { paintJson(); }
  });
  $('#jsonapply').addEventListener('click', applyJson);
  $('#jsonclose').addEventListener('click', () => { jsonVisible = false; $('#jsonpanel').classList.remove('visible'); });
  undoStack = [];
  renderAll();
  vscode.postMessage({ type: 'ready' });
});
})();
`;

