<div class="fr-json" id="jsonpanel">
  <div class="fr-toolbar">
    <button id="jsonapply">Apply</button>
    <button id="jsonclose">Close</button>
    <span id="jsonstatus" class="meta-chip"></span>
  </div>
  <textarea id="jsontext" spellcheck="false" wrap="off"></textarea>
</div>
<div class="fr-modal" id="modal"><div class="sheet" id="sheet"></div></div>
`;

function paletteHtml(): string {
	const groups: string[] = [];
	for (const group of PALETTE) {
		const items = group.types
			.map(type => `<button draggable="true" data-type="${escapeHtmlAttribute(type)}">+ ${escapeHtmlAttribute(type)}</button>`)
			.join('');
		groups.push(`<h3>${escapeHtmlAttribute(group.category)}</h3>${items}`);
	}
	return groups.join('');
}

function escapeHtmlAttribute(value: string): string {
	return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * Builds the DocType Studio document. The delete button only becomes active for custom
 * DocTypes once the initializer posts its init payload.
 */
export function buildDoctypeEditorDocument(): string {
	const script = SCRIPT
		.replace('fr-toolbar button, .fr-json button', 'fr-toolbar button, .fr-json button')
		.replace('fr-toolbar .meta-chip', 'fr-toolbar .meta-chip');
	return buildFrappeDocument({
		nonce: newFrappeNonce(),
		styles: STYLES,
		body: BODY
			.replace('__PALETTE_GROUPS_HTML__', paletteHtml())
			.replace('__PLACEHOLDER__', '' ),
		scripts: script
	});
}

