 *--------------------------------------------------------------------------------------------*/

import { CancellationToken } from '../../../../base/common/cancellation.js';
import { Disposable, IDisposable, toDisposable } from '../../../../base/common/lifecycle.js';
import { localize } from '../../../../nls.js';
import { ICommandService } from '../../../../platform/commands/common/commands.js';
import { IConfigurationService } from '../../../../platform/configuration/common/configuration.js';
import { IContextKeyService } from '../../../../platform/contextkey/common/contextkey.js';
import { IHoverService } from '../../../../platform/hover/browser/hover.js';
import { IInstantiationService } from '../../../../platform/instantiation/common/instantiation.js';
import { IOpenerService } from '../../../../platform/opener/common/opener.js';
import { IKeybindingService } from '../../../../platform/keybinding/common/keybinding.js';
import { IContextMenuService } from '../../../../platform/contextview/browser/contextView.js';
import { IThemeService } from '../../../../platform/theme/common/themeService.js';
import { IViewPaneOptions, ViewPane } from '../../../../browser/parts/views/viewPane.js';
import { IViewDescriptorService } from '../../../../common/views.js';
import { JsonRecord } from '../common/frappeTypes.js';
import { listDocTypes, listModules } from '../connection/doctypeService.js';
import { IFrappeApp } from './frappeSiteInfo.js';
import { FrappeStudioCommandId } from '../common/frappeCommandIds.js';

/**
 * Sidebar panes for the Frappe Studio view container. They show live site data loaded
 * through the connection service; when no site is connected they show the welcome CTA.
 *
 * DOM is kept simple and native: a search input, a status line and a list; interactions run
 * well-established workbench commands instead of bespoke CSS-heavy chrome.
 */

const codiconFor = (name: string): string => `<span class="codicon codicon-${name}"></span>`;

abstract class FrappeListPane extends ViewPane implements IDisposable {
	abstract readonly paneTitle: string;

	protected listElement!: HTMLUListElement;
	protected statusElement!: HTMLSpanElement;
	protected searchInput!: HTMLInputElement;
	protected allRows: { id: string; label: string; detail: string; icon: string; args: unknown[]; commandId: string }[] = [];
	protected filter = '';
	private readonly disposables: Disposable[] = [];

	constructor(
		options: IViewPaneOptions,
		@IKeybindingService keybindingService: IKeybindingService,
		@IContextMenuService contextMenuService: IContextMenuService,
		@IConfigurationService configurationService: IConfigurationService,
		@IContextKeyService contextKeyService: IContextKeyService,
		@IViewDescriptorService viewDescriptorService: IViewDescriptorService,
		@IInstantiationService protected readonly instantiationService: IInstantiationService,
		@IOpenerService openerService: IOpenerService,
		@IThemeService themeService: IThemeService,
		@IHoverService hoverService: IHoverService
	) {
		super(options, keybindingService, contextMenuService, configurationService, contextKeyService, viewDescriptorService, instantiationService, openerService, themeService, hoverService);
	}

	protected buildBase(parent: HTMLElement): void {
		const wrapper = document.createElement('div');
		wrapper.style.cssText = 'display:flex;flex-direction:column;height:100%';
		const search = document.createElement('input');
		search.type = 'text';
		search.placeholder = localize('frappeStudio.filterPlaceholder', 'Filter...');
		search.style.cssText = 'margin:6px 10px 2px;padding:3px 6px;border:1px solid var(--vscode-input-border);background:var(--vscode-input-background);color:var(--vscode-input-foreground);width:calc(100% - 20px)';
		search.addEventListener('input', () => {
			this.filter = search.value;
			this.paint();
		});
		const statusBar = document.createElement('div');
		statusBar.style.cssText = 'padding:2px 10px;color:var(--vscode-descriptionForeground);font-size:12px';
		this.statusElement = document.createElement('span');
		const refresh = document.createElement('button');
		refresh.append(localize('frappeStudio.refresh', 'Refresh'));
		refresh.style.cssText = 'margin-left:auto;cursor:pointer';
		refresh.addEventListener('click', () => this.refresh());
		statusBar.append(this.statusElement, refresh);
		this.listElement = document.createElement('ul');
		this.listElement.style.cssText = 'list-style:none;margin:4px 6px;padding:0;overflow:auto;flex:1';
		wrapper.append(search, statusBar, this.listElement);
		parent.appendChild(wrapper);
		this.renderEmpty(localize('frappeStudioLoading', 'Loading\u2026'));
	}

	protected renderEmpty(message: string): void {
		this.allRows = [];
		this.statusElement.textContent = message;
		this.paint();
	}

	protected paint(): void {
		this.listElement.innerHTML = '';
		const rows = this.allRows.filter(r => !this.filter || `${r.label} ${r.detail}`.toLowerCase().includes(this.filter.toLowerCase()));
		for (const row of rows) {
			const item = document.createElement('li');
			item.style.cssText = 'display:flex;gap:6px;align-items:center;padding:2px 4px;border-radius:3px;cursor:pointer';
			item.addEventListener('mouseenter', () => item.style.background = 'var(--vscode-list-hoverBackground)');
			item.addEventListener('mouseleave', () => item.style.background = 'transparent');
			item.innerHTML = `${codiconFor(row.icon)}<span style="flex:1">${this.escapeHtml(row.label)}</span><span style="font-size:11px;color:var(--vscode-descriptionForeground)">${this.escapeHtml(row.detail)}</span>`;
			item.addEventListener('click', () => this.instantiationService.invokeFunction(accessor => {
				const commandService = accessor.get(ICommandService);
				void commandService.executeCommand(row.commandId, ...row.args);
			}));
			this.listElement.appendChild(item);
		}
		if (!rows.length && this.allRows.length) {
			this.listElement.innerHTML = '';
			const empty = document.createElement('li');
			empty.style.padding = '6px';
			empty.style.color = 'var(--vscode-descriptionForeground)';
			empty.textContent = localize('frappeStudio.noMatches', 'No entries match the filter.');
			this.listElement.appendChild(empty);
		}
	}

	protected escapeHtml(value: string): string {
		return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
	}

	public override refresh(): void {
		// implemented by each pane
	}

	override dispose(): void {
		for (const d of this.disposables) {
			d.dispose();
		}
		super.dispose();
	}
}

import { workbenchEnergySaveProfile } from './frappeSiteInfo.js';
import { ISiteConnectionService } from '../connection/connectionService.js';

/** Localizes the site data service types without leaking them into the view layer. */
export interface IFrappeStudioOverview { readonly connectedLabel: string }

export class FrappeOverviewPane extends FrappeListPane {
	readonly paneTitle = localize('frappeStudio.overview', 'Frappe Studio');

	constructor(
		options: IViewPaneOptions,
		@IKeybindingService keybindingService: IKeybindingService,
		@IContextMenuService contextMenuService: IContextMenuService,
		@IConfigurationService configurationService: IConfigurationService,
		@IContextKeyService contextKeyService: IContextKeyService,
		@IViewDescriptorService viewDescriptorService: IViewDescriptorService,
		@IInstantiationService instantiationService: IInstantiationService,
		@IOpenerService openerService: IOpenerService,
		@IThemeService themeService: IThemeService,
		@IHoverService hoverService: IHoverService,
		@ISiteConnectionService private readonly connectionService: ISiteConnectionService
	) {
		super(options, keybindingService, contextMenuService, configurationService, contextKeyService, viewDescriptorService, instantiationService, openerService, themeService, hoverService);
	}

	protected buildBase(parent: HTMLElement): void {
	}

	protected override renderBody(parent: HTMLElement): void {
		this.buildBase(parent);
	}

	public override refresh(): void {
		const overview = workbenchEnergySaveProfile(this.connectionService);
		this.statusElement.textContent = overview.connectedLabel;
		this.allRows = [];
		for (const row of overview.rows) {
			this.allRows.push(row);
		}
		this.paint();
	}
}

export class FrappeAppsPane extends FrappeListPane {
	readonly paneTitle = localize('frappeStudio.apps', 'Apps');

	constructor(
		options: IViewPaneOptions,
		@IKeybindingService keybindingService: IKeybindingService,
		@IContextMenuService contextMenuService: IContextMenuService,
		@IConfigurationService configurationService: IConfigurationService,
		@IContextKeyService contextKeyService: IContextKeyService,
		@IViewDescriptorService viewDescriptorService: IViewDescriptorService,
		instantiationService: IInstantiationService,
		@IOpenerService openerService: IOpenerService,
		@IThemeService themeService: IThemeService,
		@IHoverService hoverService: IHoverService,
		@ISiteConnectionService private readonly connectionService: ISiteConnectionService
	) {
		super(options, keybindingService, contextMenuService, configurationService, contextKeyService, viewDescriptorService, instantiationService, openerService, themeService, hoverService);
	}

	protected override renderBody(parent: HTMLElement): void {
		this.buildBase(parent);
	}

	public override refresh(): void {
		const session = this.connectionService.getSessions().find(s => s.connection.id === this.connectionService.activeSessionId) ?? this.connectionService.getSessions()[0];
		if (!session?.identity) {
			this.renderEmpty(localize('frappeStudio.connectFirst', 'Connect to a site to see its apps.'));
			return;
		}
		this.statusElement.textContent = session.identity.siteName;
		this.allRows = session.identity.installedApps.map((app: IFrappeApp) => ({
			id: app.name,
			label: app.name,
			detail: app.version ?? localize('frappeStudio.unknownVersion', 'unknown version'),
			icon: 'package',
			commandId: FrappeStudioCommandId.ListAppModules,
			args: [session.connection.id, app.name]
		}));
		this.paint();
	}
}

export class FrappeDocTypesPane extends FrappeListPane {
	readonly paneTitle = localize('frappeStudio.doctypes', 'DocTypes');

	private readonly loading = toDisposable(() => undefined);

	constructor(
		options: IViewPaneOptions,
		@IKeybindingService keybindingService: IKeybindingService,
		@IContextMenuService contextMenuService: IContextMenuService,
		@IConfigurationService configurationService: IConfigurationService,
		@IContextKeyService contextKeyService: IContextKeyService,
		@IViewDescriptorService viewDescriptorService: IViewDescriptorService,
		@IInstantiationService instantiationService: IInstantiationService,
		@IOpenerService openerService: IOpenerService,
		@IThemeService themeService: IThemeService,
		@IHoverService hoverService: IHoverService,
		@ISiteConnectionService private readonly connectionService: ISiteConnectionService,
		@IContextKeyService private readonly contextKeyService2: IContextKeyService
	) {
		super(options, keybindingService, contextMenuService, configurationService, contextKeyService, viewDescriptorService, instantiationService, openerService, themeService, hoverService);
		this.loading.dispose();
	}

	protected override renderBody(parent: HTMLElement): void {
		this.buildBase(parent);
	}

	public override refresh(): void {
		const token = CancellationToken.None;
		const connectionId = this.connectionService.activeSessionId;
		const session = connectionId ? this.connectionService.getSession(connectionId) : undefined;
		if (!session) {
			this.renderEmpty(localize('frappeStudio.connectFirst', 'Connect to a site to browse its DocTypes.'));
			return;
		}
		this.renderEmpty(localize('frappeStudio.loadingDocTypes', 'Loading DocTypes\u2026'));
		void listDocTypes(session.client, token).then(docs => {
			this.allRows = docs.filter(doc => doc.name).map((doc: { name: string; standard?: boolean }) => ({
				id: doc.name,
				label: doc.name,
				detail: doc.standard ? localize('frappeStudio.standard', 'standard') : localize('frappeStudio.custom', 'custom'),
				icon: doc.standard ? 'file-type' : 'file-submodule',
				commandId: FrappeStudioCommandId.OpenDoctypeEditor,
				args: [session.connection.id, doc.name]
			}));
			this.statusElement.textContent = String(docs.length);
			this.paint();
		}, () => {
			this.renderEmpty(localize('frappeStudio.loadFailed', 'Could not load DocTypes. Reconnect to the site and retry.'));
		});
	}

	filtersForModule(moduleName: string): void {
		this.filter = moduleName;
		this.paint();
	}
}

export function createListPaneElement(pane: FrappeListPane): IDisposable {
	return toDisposable(() => pane.dispose());
}

export interface IModuleRow { readonly name: string; readonly app?: string }

export function rowsForModules(modules: readonly IModuleRow[]): { id: string; label: string; detail: string; icon: string }[] {
	return modules.map(m => ({ id: m.name, label: m.name, detail: m.app ?? '', icon: 'symbol-namespace' }));
}

export function describeRecord(record: JsonRecord): string {
	return String(record['name'] ?? '');
}

