	}
] as readonly IViewDescriptor[], frappeViewContainer);

Registry.as<IViewsRegistry>(ViewExtensions.ViewsRegistry).registerViewWelcomeContent(OVERVIEW_VIEW_ID, {
	content: localize('frappeStudio.welcome', "Frappe Studio\n\nYour Frappe Development Environment.\n\n[Connect to a Frappe Site](command:{0})\n[Manage Connections](command:{1})\nTo see more, connect to a site first.", FrappeStudioCommandId.Connect, FrappeStudioCommandId.ManageConnections)
} as never);

// ---- settings ------------------------------------------------------------------------------

Registry.as<IConfigurationRegistry>(ConfigurationExtensions.Configuration).registerConfiguration({
	id: 'frappe-studio',
	order: 120,
	title: localize('frappeStudio.settingsTitle', 'Frappe Studio'),
	type: 'object',
	properties: {
		'frappe-studio.connection.timeoutSeconds': {
			type: 'number',
