			minimum: 5,
			description: localize('frappeStudio.timeoutSetting', 'Number of seconds to wait before considering a Frappe request failed.')
		},
		'frappe-studio.connection.allowInsecureTls': {
			type: 'boolean',
			default: false,
			deprecationMessage: localize('frappeStudio.allowInsecureDeprecation', 'Disabling TLS validation is unsafe. Use per-connection trust in the connection wizard instead. This setting has no effect.')
		},
		'frappe-studio.bench.contexts': {
			type: 'array',
			items: { type: 'string' },
			default: [],
			description: localize('frappeStudio.benchContexts', 'Local Bench root directories known to this IDE, e.g. /home/frappe/frappe-bench. Bench commands run in the integrated terminal with this working directory.')
		},
		'frappe-studio.bench.useWslOnWindows': {
			type: 'boolean',
			default: false,
			description: localize('frappeStudio.benchWsl', 'Run Bench commands through WSL on Windows.')
		},
		'frappe-studio.database.readOnly': {
			type: 'boolean',
			default: true,
			description: localize('frappeStudio.dbReadOnly', 'Keep the Database Explorer strictly read-only. Destructive database operations always stay behind explicit confirmations.')
		}
	}
} as unknown as ConfigurationExtensionsAlias | never);

// ---- status bar ------------------------------------------------------------------------------

class FrappeStudioStatusBarItem implements IWorkbenchContribution {

	static readonly ID = 'frappeStudio.statusBar';

	private entryAccessor = this.statusbarService.addEntry({
		name: localize('frappeStudio.statusEntry', 'Frappe Studio Connection'),
		text: localize('frappeStudio.statusDisconnected', 'Frappe: Not connected'),
		tooltip: localize('frappeStudio.statusTooltip', 'Active Frappe site connection'),
		command: { id: FrappeStudioCommandId.ManageConnections, title: localize('frappeStudio.statusManage', 'Manage Connections') }
	}, StatusbarAlignment.RIGHT, 1050);

	constructor(
		@IStatusbarService private readonly statusbarService: IStatusbarService,
		@ISiteConnectionService connectionService: ISiteConnectionService
	) {
		this._register(connectionService.onDidChangeActiveConnection(() => this.paint(connectionService)));
		this._register(connectionService.onDidChangeSessionState(() => this.paint(connectionService)));
		this.paint(connectionService);
	}

	private paint(connectionService: ISiteConnectionService): void {
		const session = connectionService.getSessions().find(s => s.connection.id === connectionService.activeSessionId) ?? connectionService.getSessions()[0];
		const text = session && session.state === FrappeConnectionState.Connected
			? `Frappe: ${session.connection.label}`
			: localize('frappeStudio.statusDisconnected', 'Frappe: Not connected');
		const updatedEntry = {
			name: localize('frappeStudio.statusEntry', 'Frappe Studio Connection'),
			text,
			tooltip: localize('frappeStudio.statusTooltip', 'Active Frappe site connection'),
			command: { id: FrappeStudioCommandId.ManageConnections, title: localize('frappeStudio.statusManage', 'Manage Connections') }
		};
		this.entryAccessor.update(updatedEntry);
	}

	dispose(): void {
		this.entryAccessor.dispose();
	}
}

registerWorkbenchContribution2(FrappeStudioStatusBarItem.ID, FrappeStudioStatusBarItem, WorkbenchPhase.BlockRestore);

