	constructor() {
		super({
			id: FrappeStudioCommandId.Connect,
			title: localize2('frappeStudio.connectCommand', 'Frappe Studio: Connect to a Frappe Site'),
			category: localize2('frappeStudio.category', 'Frappe Studio'),
			f1: true
		});
	}
	async run(accessor: Parameters<never> extends never ? never : never, ...args: unknown[]): Promise<void> { // TODO fix signature
		//
	}
}

registerAction2(ConnectToSiteAction);

