class ConnectCommand extends Action2 {
	constructor() {
		super({
			id: FrappeStudioCommandId.Connect,
			title: localize2('frappeStudio.connectCommand', 'Connect to a Frappe Site'),
			category,
			f1: true
		});
	}

	async run(accessor: ServicesAccessor): Promise<void> {
		const quickInput = accessor.get(IQuickInputService);
		const instantiationService = accessor.get(IInstantiationService);
		const connectionService = accessor.get(ISiteConnectionService);
		const notifications = accessor.get(INotificationService);
		const logService = accessor.get(ILogService);

		// Step 1: the site URL
		const siteUrl = await quickInput.input({ ignoreFocusLost: false, value: 'http://localhost:8000', prompt: localize('frappeStudio.enterUrl', 'Site URL, for example https://erp.example.com or http://localhost:8000'), title: localize('frappeStudio.wizardStep1', 'Connect Step 1 of 2: Site URL') });
		if (!siteUrl) {
			return;
		}
		let normalized;
		try {
			normalized = normalizeSiteUrl(siteUrl);
		} catch (error) {
			notifications.error(localize('frappeStudio.invalidUrl', '{0}', describeError(error)));
			return;
		}

		// Step 2: credentials; Administrator is the traditional site-wide super user
		const username = await quickInput.input({
			value: 'Administrator',
			prompt: localize('frappeStudio.enterUser', 'Username'),
			title: localize('frappeStudio.wizardStep2', 'Connect Step 2 of 2: Credentials')
		});
		if (username === undefined) {
			return;
		}
		const password = await quickInput.input({ password: true, prompt: localize('frappeStudio.enterPassword', 'Password (stored only in the operating-system keychain)'), title: localize('frappeStudio.wizardStep2', 'Connect Step 2 of 2: Credentials') });
		if (password === undefined) {
			return;
		}
		try {
			const client = new FrappeClient(normalized, accessor.get(IRequestService), logService);
			try {
				await client.getLoggedUser(CancellationToken.None);
			} catch (e) {
				// Expected on an unauthenticated session; ignore, reachability was already probed.
			}
			await connectionService.connect(siteUrl, username, password, { rememberPassword: true });
			notifications.info(localize('frappeStudio.connected', 'Connected to {0} as {1}', normalized.origin, username));
			CommandsRegistry.getCommand(FrappeStudioCommandId.OpenOverview)?.run(accessor.get, undefined, []);
		} catch (error) {
			const friendly = error instanceof FrappeAuthenticationError
				? error.message
				: error instanceof SiteUnreachableError
					? localize('frappeStudio.unreachable', 'The site could not be reached: {0}', error.message)
					: error instanceof FrappeSessionExpiredError
						? localize('frappeStudio.sessionExpired', 'The site rejected the session; try again.')
						: describeError(error);
			notifications.error(friendly);
		}
	}
}

class ManageConnectionsCommand extends AbstractFrappeCommand {
	constructor() {
		super({
			id: FrappeStudioCommandId.ManageConnections,
			title: localize2('frappeStudio.manageConnections', 'Manage Connections'),
			category,
			f1: true,
			menu: {
				id: MenuId.CommandPalette,
				group: '1_connect'
			}
		});
	}

	async run(accessor: ServicesAccessor): Promise<void> {
		const quickInput = accessor.get(IQuickInputService);
		const connectionService = accessor.get(ISiteConnectionService);
		const sessions = connectionService.getSessions();
		const storeLabel = localize('frappeStudio.store', 'Store the connection without a live session');
		const items: (IQuickPickItem & { value: () => Promise<void> })[] = [];
		for (const session of sessions) {
			items.push({
				label: session.connection.label,
				description: session.state,
				detail: session.connection.username,
				value: async () => {
					connectionService.setActiveSession(session.connection.id);
				}
			});
		}
		for (const connection of connectionService.getConnections()) {
			if (!sessions.some(s => s.connection.id === connection.id)) {
				items.push({
					label: connection.label,
					description: storeLabel,
					detail: connection.username,
					value: async () => {
						await connectionService.reconnect(connection.id);
					}
				});
			}
		}
		items.push({
			label: localize('frappeStudio.addConnection', 'Add a connection...'),
			value: async () => void accessor.get(ICommandService).executeCommand(FrappeStudioCommandId.Connect)
		});
		items.push({
			label: localize('frappeStudio.forgetConnection', 'Forget the active connection...'),
			value: async () => {
				const activeId = connectionService.activeSessionId;
				if (activeId) {
					await connectionService.forget(activeId);
				}
			}
		});
		const picker = quickInput.createQuickPick<IQuickPickItem>();
		picker.title = localize('frappeStudio.connections', 'Frappe Studio Connections');
		picker.matchOnDetail = true;
		picker.ignoreFocusOut = true;
		picker.placeholder = localize('frappeStudio.connectionsPrompt', 'Click the entry to make its session active');
		picker.items = items;
		picker.onDidAccept(() => {
			const selected = picker.activeItems[0] as IQuickPickItem & { value: () => Promise<void> } | undefined;
			void selected?.value();
			picker.hide();
		});
		picker.show();
	}
}

