// ---- Bench manager ---------------------------------------------------------------------------------

class RunBenchCommand extends Action2 {
	constructor() {
		super({
			id: FrappeStudioCommandId.RunBenchCommand,
			title: localize2('frappeStudio.runBenchCommand', 'Run a Bench Command'),
			category,
			f1: true
		});
	}

	async run(accessor: ServicesAccessor): Promise<void> {
		const configurationService = accessor.get(IConfigurationService);
		const quickInput = accessor.get(IQuickInputService);
		const terminalService = accessor.get(ITerminalService);
		const notifications = accessor.get(INotificationService);
		const contexts = configurationService.getValue<string[]>('frappe-studio.bench.contexts') ?? [];
		if (!Array.isArray(contexts) || !contexts.length) {
			notifications.info(localize('frappeStudio.noBenchContexts', 'Add bench directories to the frappe-studio.bench.contexts setting first.'));
			return;
		}
		const picks: (IQuickPickItem & { path: string })[] | (IQuickPickItem & { path?: string })[] = contexts.map(path => ({ label: path, path }));
		const selection = await quickInput.pick(picks, {
			title: localize('frappeStudio.pickBench', 'Bench environment'),
			ignoreFocusOut: true
		});
		if (!selection || !selection.path) {
			return;
		}
		const commands = [
			['start', 'bench start'],
			['stop', 'pkill -f "bench serve"'],
			['clear-cache', 'bench clear-cache'],
			['clear-website-cache', 'bench clear-website-cache'],
			['backup', 'bench backup --with-files'],
			['migrate', 'bench migrate'],
			['list-apps', 'bench list-apps'],
			['build', 'bench build'],
			['get-app', 'bench get-app'],
			['new-app', 'bench new-app'],
			['new-site', 'bench new-site'],
			['drop-site', 'bench drop-site']
		];
		const commandPicks: (IQuickPickItem & { commandText: string })[] = commands.map(([label, commandText]) => ({ label, commandText }));
		const commandPick = await quickInput.pick(commandPicks, {
			title: localize('frappeStudio.pickBenchCommand', 'Bench command'),
			ignoreFocusOut: true
		});
		if (!commandPick) {
			return;
		}
		if (['migrate', 'drop-site', 'new-site', 'backup'].includes(commandPick.label)) {
			const confirm = await quickInput.pick(
				[{ label: localize('frappeStudio.destructiveConfirm', 'Yes, run it'), run: true }, { label: localize('frappeStudio.destructiveCancel', 'No, cancel'), run: false }],
				{ title: localize('frappeStudio.destructiveTitle', 'This bench command changes data. Run "{0}"?', commandPick.commandText) } as never
			);
			if (!confirm || !confirm.run) {
				return;
			}
		}
		const useWsl = configurationService.getValue<boolean>('frappe-studio.bench.useWslOnWindows') && process.platform === 'win32';
		const finalCommand = useWsl
			? `wsl.exe --cd "${selection.path}" -- ${commandPick.commandText}`
			: commandPick.commandText;
		const terminal = terminalService.createTerminal({ name: `Bench (${selection.label})`, cwd: URI.file(selection.path) });
		terminal.show();
		terminal.sendText(finalCommand, true);
	}
}

registerAction2(RunBenchCommand);

