class ShowAboutCommand extends Action2 {
	constructor() {
		super({
			id: FrappeStudioCommandId.ShowAbout,
			title: localize2('frappeStudio.about', 'About Frappe Studio'),
			category,
			f1: true
		});
	}

	async run(accessor: ServicesAccessor): Promise<void> {
		const productService = accessor.get(IProductService);
		const connectionService = accessor.get(ISiteConnectionService);
		const notifications = accessor.get(INotificationService);
		const session = connectionService.getSessions().find(s => s.connection.id === connectionService.activeSessionId) ?? connectionService.getSessions()[0];
		const lines = [
			`${productService.nameLong} (Frappe Studio) ${productService.version ?? ''}`,
			session ? `Connected site: ${session.connection.origin} (${session.connection.username})` : 'No active connection',
			session?.identity?.frappeVersion ? `Frappe version: ${session.identity.frappeVersion}` : 'Frappe version: unknown',
			`Developer mode: ${session?.identity ? session.identity.developerMode : 'unknown'}`
		];
		notifications.info(lines.join('\n'));
	}
}

registerAction2(ShowAboutCommand);

